// ==UserScript==
// @name         Ice Fishing Complete Telemetry & Multiplier Console HUD
// @namespace    http://tampermonkey.net/
// @version      6.1
// @description  Full telemetry logger: tracks exact outcomes, historical multipliers, landed multipliers, and live dynamic picks
// @match        *://*/*
// @run-at       document-start
// @grant        none
// ==/UserScript==

(function() {
    'use strict';
    const ICONS = {
        Leaf1: "data:image/webp;base64,",
        Leaf2: "data:image/webp;base64,",
        LilBlues: "data:image/webp;base64,",
        BigOranges: "data:image/webp;base64,",
        HugeReds: "data:image/webp;base64,"
    };


    let history = [];
    let currentDroughts = { HugeReds: 0, BigOranges: 0, LilBlues: 0 };
    let lastSpinInfo = { sector: null, direction: 'Clockwise' };
    let activeWheelMultipliers = {}; // Multipliers assigned during wheelSpinning
    let multiplierHistoryLog = [];   // Log of rounds that hit multipliers

    let stats = {
        Leaf1: 0,
        Leaf2: 0,
        LilBlues: 0,
        BigOranges: 0,
        HugeReds: 0,
        total: 0,
        totalMultipliersHit: 0,
        maxMultiplierHit: 1
    };

    function initHUD() {
        if (window.top !== window.self) return;
        if (document.getElementById('ice-fishing-hud')) return;

        const hud = document.createElement('div');
        hud.id = 'ice-fishing-hud';
        hud.innerHTML = `
            <!-- HEADER -->
            <div id="hud-header" style="cursor: move; padding: 10px 14px; background: #001100; border-bottom: 2px solid #00ff66; display: flex; justify-content: space-between; align-items: center; border-radius: 8px 8px 0 0;">
                <span style="font-weight: bold; color: #00ff66; font-family: 'Courier New', monospace; font-size: 14px; letter-spacing: 1px;">
                    >_ TELEMETRY CONSOLE
                </span>
                <span id="hud-status" style="font-size: 11px; color: #00ff66; font-family: monospace; font-weight: bold;">[ONLINE]</span>
            </div>

            <div style="padding: 12px 15px; font-family: 'Courier New', monospace; font-size: 12px; color: #00ff66; line-height: 1.4;">
                
                <!-- EARLY FLASH BOX -->
                <div id="early-flash-box" style="margin-bottom: 10px; padding: 8px; background: rgba(0, 255, 102, 0.08); border: 1px solid #00ff66; border-radius: 4px; text-align: center;">
                    <div style="font-size: 10px; color: #88ff88; letter-spacing: 1px;">// ADVANCE RESULT (4s AHEAD)</div>
                    <div id="early-sector" style="font-size: 18px; font-weight: bold; color: #00ff66; margin-top: 3px; text-shadow: 0 0 10px #00ff66;">
                        AWAITING SPIN...
                    </div>
                    <div id="early-multiplier" style="font-size: 12px; font-weight: bold; color: #ffea00; margin-top: 2px;">
                        --
                    </div>
                </div>

                <!-- PREDICTED PICKS (DYNAMIC MARKOV + DROUGHT ENSEMBLE) -->
                <div style="margin-bottom: 10px; background: #001a05; padding: 8px 10px; border-left: 3px solid #00ff66; border-radius: 3px;">
                    <div style="display:flex; justify-content:space-between; margin-bottom: 4px;">
                        <span style="font-size: 10px; color: #55bb55; text-transform: uppercase;">// NEXT ROUND PICKS:</span>
                        <span id="pred-model-tag" style="font-size: 9px; color: #88ff88;">[INIT]</span>
                    </div>
                    <div id="pred-top3" style="font-size: 12px; font-weight: bold; color: #ffffff;">
                        Analyzing live factors...
                    </div>
                </div>

                <!-- LIVE ODDS & HISTORICAL PERCENTAGES -->
                <div style="margin-bottom: 10px; border-top: 1px dashed #004411; padding-top: 6px;">
                    <div style="font-size: 10px; color: #55bb55; margin-bottom: 6px;">// LIVE PROBABILITY MATRIX:</div>
                    <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 3px;">
                        <span style="display:flex; align-items:center; gap:6px;"><img src="data:image/webp;base64," style="width:18px;height:18px;vertical-align:middle;border-radius:50%;"> Light Leaf (L1):</span>
                        <b id="pct-l1" style="color: #00ff66;">--%</b>
                    </div>
                    <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 3px;">
                        <span style="display:flex; align-items:center; gap:6px;"><img src="data:image/webp;base64," style="width:18px;height:18px;vertical-align:middle;border-radius:50%;"> Dark Leaf (L2):</span>
                        <b id="pct-l2" style="color: #00ff66;">--%</b>
                    </div>
                    <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 3px;">
                        <span style="display:flex; align-items:center; gap:6px;"><img src="data:image/webp;base64," style="width:18px;height:18px;vertical-align:middle;border-radius:50%;"> Lil' Blues:</span>
                        <b id="pct-blues" style="color: #33ccff;">--%</b>
                    </div>
                    <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 3px;">
                        <span style="display:flex; align-items:center; gap:6px;"><img src="data:image/webp;base64," style="width:18px;height:18px;vertical-align:middle;border-radius:50%;"> Big Oranges:</span>
                        <b id="pct-oranges" style="color: #ffaa33;">--%</b>
                    </div>
                    <div style="display: flex; justify-content: space-between; align-items: center;">
                        <span style="display:flex; align-items:center; gap:6px;"><img src="data:image/webp;base64," style="width:18px;height:18px;vertical-align:middle;border-radius:50%;"> Huge Reds:</span>
                        <b id="pct-reds" style="color: #ff4444;">--%</b>
                    </div>
                </div>

                <!-- MULTIPLIER TELEMETRY TRACKER -->
                <div style="margin-bottom: 10px; border-top: 1px dashed #004411; padding-top: 6px; background: rgba(255, 234, 0, 0.04); padding: 6px; border-radius: 4px;">
                    <div style="font-size: 10px; color: #ffea00; margin-bottom: 4px; font-weight: bold;">⚡ MULTIPLIER TRACKER:</div>
                    <div style="display: flex; justify-content: space-between; font-size: 11px; margin-bottom: 2px;">
                        <span>Hit Frequency:</span>
                        <b id="mult-freq" style="color: #ffea00;">-- / -- spins (--%)</b>
                    </div>
                    <div style="display: flex; justify-content: space-between; font-size: 11px; margin-bottom: 2px;">
                        <span>Max Mult Observed:</span>
                        <b id="mult-max" style="color: #ff5500;">--x</b>
                    </div>
                    <div style="font-size: 10px; color: #a0aec0; margin-top: 3px;" id="mult-last-hits">
                        Recent: Waiting for hits...
                    </div>
                </div>

                <!-- DROUGHT COUNTERS -->
                <div style="border-top: 1px dashed #004411; padding-top: 6px; font-size: 11px;">
                    <div style="color: #55bb55; margin-bottom: 4px;">// DROUGHT TRACKER (ROUNDS AGO):</div>
                    <div style="display: flex; justify-content: space-between; align-items: center;">
                        <span style="display:flex; align-items:center; gap:4px; color: #ff6666;"><img src="data:image/webp;base64," style="width:15px;height:15px;vertical-align:middle;border-radius:50%;"> Reds: <b id="dr-reds">0r</b></span>
                        <span style="display:flex; align-items:center; gap:4px; color: #ffbb44;"><img src="data:image/webp;base64," style="width:15px;height:15px;vertical-align:middle;border-radius:50%;"> Oranges: <b id="dr-oranges">0r</b></span>
                        <span style="display:flex; align-items:center; gap:4px; color: #44ddff;"><img src="data:image/webp;base64," style="width:15px;height:15px;vertical-align:middle;border-radius:50%;"> Blues: <b id="dr-blues">0r</b></span>
                    </div>
                </div>

                <!-- SPIN TELEMETRY -->
                <div style="border-top: 1px dashed #004411; margin-top: 6px; padding-top: 5px; display: flex; justify-content: space-between; font-size: 10px; color: #44aa55;">
                    <span>Start: <b id="spin-start" style="color: #00ff66;">--</b></span>
                    <span>Spin: <b id="spin-dir" style="color: #00ff66;">--</b></span>
                    <span>Mults Active: <b id="spin-mult-count" style="color: #ffea00;">0</b></span>
                </div>
            </div>
        `;

        Object.assign(hud.style, {
            position: 'fixed',
            top: '25px',
            right: '25px',
            width: '320px',
            background: 'rgba(0, 10, 2, 0.96)',
            border: '2px solid #00ff66',
            borderRadius: '8px',
            boxShadow: '0 0 20px rgba(0, 255, 102, 0.25)',
            zIndex: '9999999',
            fontFamily: 'monospace',
            pointerEvents: 'auto'
        });

        // Draggable
        let isDragging = false, startX, startY, startLeft, startTop;
        const header = hud.querySelector('#hud-header');
        header.onmousedown = (e) => {
            isDragging = true;
            startX = e.clientX;
            startY = e.clientY;
            startLeft = hud.offsetLeft;
            startTop = hud.offsetTop;
            document.onmousemove = (e) => {
                if (!isDragging) return;
                hud.style.left = `${startLeft + e.clientX - startX}px`;
                hud.style.top = `${startTop + e.clientY - startY}px`;
                hud.style.right = 'auto';
            };
            document.onmouseup = () => { isDragging = false; document.onmousemove = null; };
        };

        document.documentElement.appendChild(hud);
    }

    function computeFullTelemetry(results, spinInfo) {
        if (!results || !results.length) return;
        const total = results.length;
        stats.total = total;
        stats.Leaf1 = results.filter(r => r.result === 'Leaf1').length;
        stats.Leaf2 = results.filter(r => r.result === 'Leaf2').length;
        stats.LilBlues = results.filter(r => r.result === 'LilBlues').length;
        stats.BigOranges = results.filter(r => r.result === 'BigOranges').length;
        stats.HugeReds = results.filter(r => r.result === 'HugeReds').length;

        // MULTIPLIER AUDIT: Extract all historical multiplier hits
        const multSpins = results.filter(r => r.wheelMultiplier && r.wheelMultiplier.value);
        stats.totalMultipliersHit = multSpins.length;
        stats.maxMultiplierHit = multSpins.length > 0 ? Math.max(...multSpins.map(m => m.wheelMultiplier.value)) : 1;
        const recentMults = multSpins.slice(0, 4).map(m => `${m.result}:${m.wheelMultiplier.value}x`);

        // Drought calculation
        const rev = [...results].reverse();
        currentDroughts.HugeReds = rev.findIndex(r => r.result === 'HugeReds');
        if (currentDroughts.HugeReds === -1) currentDroughts.HugeReds = total;

        currentDroughts.BigOranges = rev.findIndex(r => r.result === 'BigOranges');
        if (currentDroughts.BigOranges === -1) currentDroughts.BigOranges = total;

        currentDroughts.LilBlues = rev.findIndex(r => r.result === 'LilBlues');
        if (currentDroughts.LilBlues === -1) currentDroughts.LilBlues = total;

        let p_l1 = (stats.Leaf1 / total) * 100;
        let p_l2 = (stats.Leaf2 / total) * 100;
        let p_lb = (stats.LilBlues / total) * 100;
        let p_bo = (stats.BigOranges / total) * 100;
        let p_hr = (stats.HugeReds / total) * 100;

        // Markov Run-length streak analysis
        const lastOutcome = results[0] ? results[0].result : '';
        let streak = 0;
        for (let i = 0; i < results.length; i++) {
            if (results[i].result === lastOutcome) streak++;
            else break;
        }

        const dir = spinInfo ? spinInfo.direction : lastSpinInfo.direction;

        let picks = [];
        // Conditional flip bias after streaks
        if (lastOutcome === 'Leaf1' && streak >= 2) {
            picks.push({ name: 'Dark Leaf (L2)', reason: `Flip Bias (L1 streak ${streak})`, color: '#00ff66' });
            picks.push({ name: 'Light Leaf (L1)', reason: `Momentum Cover`, color: '#88ff88' });
        } else if (lastOutcome === 'Leaf2' && streak >= 2) {
            picks.push({ name: 'Light Leaf (L1)', reason: `Flip Bias (L2 streak ${streak})`, color: '#00ff66' });
            picks.push({ name: 'Dark Leaf (L2)', reason: `Momentum Cover`, color: '#88ff88' });
        } else {
            if (dir === 'Clockwise') {
                picks.push({ name: 'Light Leaf (L1)', reason: `CW Momentum (${p_l1.toFixed(0)}%)`, color: '#00ff66' });
                picks.push({ name: 'Dark Leaf (L2)', reason: `Cover (${p_l2.toFixed(0)}%)`, color: '#88ff88' });
            } else {
                picks.push({ name: 'Dark Leaf (L2)', reason: `CCW Momentum (${p_l2.toFixed(0)}%)`, color: '#00ff66' });
                picks.push({ name: 'Light Leaf (L1)', reason: `Cover (${p_l1.toFixed(0)}%)`, color: '#88ff88' });
            }
        }

        // Drought Urgency Pick
        const redUrgency = currentDroughts.HugeReds / 45;
        const orangeUrgency = currentDroughts.BigOranges / 20;
        const blueUrgency = currentDroughts.LilBlues / 14;

        if (redUrgency >= orangeUrgency && redUrgency >= blueUrgency && currentDroughts.HugeReds >= 25) {
            picks.push({ name: 'Huge Reds', reason: `Drought ${currentDroughts.HugeReds}r (Urgent)`, color: '#ff4444' });
        } else if (orangeUrgency >= blueUrgency && currentDroughts.BigOranges >= 15) {
            picks.push({ name: 'Big Oranges', reason: `Drought ${currentDroughts.BigOranges}r (Urgent)`, color: '#ffaa33' });
        } else if (currentDroughts.LilBlues >= 10) {
            picks.push({ name: 'Lil\' Blues', reason: `Drought ${currentDroughts.LilBlues}r (Active)`, color: '#33ccff' });
        } else {
            picks.push({ name: 'Lil\' Blues', reason: `Bonus Coverage`, color: '#33ccff' });
        }

        // Broadcast to Top Window
        window.top.postMessage({
            type: 'ICE_CONSOLE_UPDATE',
            percentages: { p_l1, p_l2, p_lb, p_bo, p_hr },
            droughts: currentDroughts,
            multipliers: {
                totalHit: stats.totalMultipliersHit,
                totalSpins: total,
                pct: ((stats.totalMultipliersHit / total) * 100).toFixed(1),
                max: stats.maxMultiplierHit,
                recent: recentMults.join(' | ')
            },
            picks: picks,
            modelTag: `[STREAK: ${streak}x ${lastOutcome === 'Leaf1' ? 'L1' : lastOutcome === 'Leaf2' ? 'L2' : 'Fish'}]`
        }, '*');
    }

    // Top Window Event Listener
    window.addEventListener('message', (e) => {
        if (!e.data) return;

        if (e.data.type === 'ICE_CONSOLE_UPDATE') {
            const p = e.data.percentages;
            const d = e.data.droughts;
            const m = e.data.multipliers;
            const picks = e.data.picks;
            const tag = e.data.modelTag;

            // Model Tag
            const tagEl = document.getElementById('pred-model-tag');
            if (tagEl && tag) tagEl.textContent = tag;

            // Percentages
            const el1 = document.getElementById('pct-l1');
            const el2 = document.getElementById('pct-l2');
            const elb = document.getElementById('pct-blues');
            const elo = document.getElementById('pct-oranges');
            const elr = document.getElementById('pct-reds');

            if (el1) el1.textContent = `${p.p_l1.toFixed(1)}%`;
            if (el2) el2.textContent = `${p.p_l2.toFixed(1)}%`;
            if (elb) elb.textContent = `${p.p_lb.toFixed(1)}%`;
            if (elo) elo.textContent = `${p.p_bo.toFixed(1)}%`;
            if (elr) elr.textContent = `${p.p_hr.toFixed(1)}%`;

            // Droughts
            const drR = document.getElementById('dr-reds');
            const drO = document.getElementById('dr-oranges');
            const drB = document.getElementById('dr-blues');
            if (drR) drR.textContent = `${d.HugeReds}r`;
            if (drO) drO.textContent = `${d.BigOranges}r`;
            if (drB) drB.textContent = `${d.LilBlues}r`;

            // Multipliers
            const mFreq = document.getElementById('mult-freq');
            const mMax = document.getElementById('mult-max');
            const mRecent = document.getElementById('mult-last-hits');
            if (mFreq) mFreq.textContent = `${m.totalHit} / ${m.totalSpins} spins (${m.pct}%)`;
            if (mMax) mMax.textContent = `${m.max}x`;
            if (mRecent) mRecent.textContent = `Recent: ${m.recent || 'None'}`;

            // Picks
            const predEl = document.getElementById('pred-top3');
            if (predEl && picks) {
                const getIconKey = (name) => {
                    if (name.includes('L1') || name.includes('Light Leaf')) return 'Leaf1';
                    if (name.includes('L2') || name.includes('Dark Leaf')) return 'Leaf2';
                    if (name.includes('Blue')) return 'LilBlues';
                    if (name.includes('Orange')) return 'BigOranges';
                    if (name.includes('Red')) return 'HugeReds';
                    return null;
                };
                predEl.innerHTML = picks.map((p, i) => {
                    const k = getIconKey(p.name);
                    const imgHtml = k && ICONS[k] ? `<img src="${ICONS[k]}" style="width:16px;height:16px;vertical-align:middle;margin-right:4px;border-radius:50%;">` : '';
                    return `
                    <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom: 3px;">
                        <span style="display:flex; align-items:center;">${i+1}.&nbsp;${imgHtml}<span style="color:${p.color}; font-weight:bold;">${p.name}</span></span>
                        <span style="font-size:10px; color:#a0aec0;">[${p.reason}]</span>
                    </div>
                `}).join('');
            }
        } 
        else if (e.data.type === 'ICE_CONSOLE_ROUND') {
            const elS = document.getElementById('spin-start');
            const elD = document.getElementById('spin-dir');
            const elMCount = document.getElementById('spin-mult-count');
            const elStatus = document.getElementById('hud-status');
            const earlyEl = document.getElementById('early-sector');
            const earlyMult = document.getElementById('early-multiplier');

            if (elS && e.data.sector !== undefined) elS.textContent = e.data.sector ?? '--';
            if (elD && e.data.dir !== undefined) elD.textContent = e.data.dir ?? '--';
            if (elMCount && e.data.activeMultCount !== undefined) elMCount.textContent = e.data.activeMultCount;

            if (elStatus && e.data.status) {
                elStatus.textContent = e.data.status;
                elStatus.style.color = e.data.statusColor || '#00ff66';
            }
            if (e.data.early) {
                if (earlyEl) {
                    const iconUrl = ICONS[e.data.early];
                    if (iconUrl) {
                        earlyEl.innerHTML = `<img src="${iconUrl}" style="width:24px;height:24px;vertical-align:middle;margin-right:8px;border-radius:50%;"> ${e.data.early}`;
                    } else {
                        earlyEl.textContent = e.data.early;
                    }
                    earlyEl.style.color = '#00ff66';
                    earlyEl.style.textShadow = '0 0 15px #00ff66';
                }
                if (earlyMult) {
                    if (e.data.wonMultiplier && e.data.wonMultiplier > 1) {
                        earlyMult.textContent = `⚡ MULTIPLIER WON: ${e.data.wonMultiplier}x!`;
                        earlyMult.style.color = '#ffea00';
                    } else {
                        earlyMult.textContent = 'Standard Payout (1x)';
                        earlyMult.style.color = '#88ff88';
                    }
                }
            } else if (e.data.resetEarly && earlyEl) {
                earlyEl.textContent = 'AWAITING SPIN...';
                earlyEl.style.color = '#88ff88';
                earlyEl.style.textShadow = 'none';
                if (earlyMult) earlyMult.textContent = '--';
            }
        }
    });

    // Clean WebSocket Interceptor
    const OriginalWebSocket = window.WebSocket;
    window.WebSocket = new Proxy(OriginalWebSocket, {
        construct(target, args) {
            const ws = new target(...args);
            const url = args[0] || '';

            if (url.includes('/icefishing/player/game/')) {
                ws.addEventListener('message', (event) => {
                    try {
                        const data = JSON.parse(event.data);
                        const type = data.type;
                        const args = data.args || {};

                        if (type === 'icefishing.spinHistory') {
                            history = args.results || [];
                            computeFullTelemetry(history, lastSpinInfo);
                        }
                        else if (type === 'icefishing.betsOpen') {
                            const info = args.spinInfo || {};
                            lastSpinInfo = info;
                            activeWheelMultipliers = {}; // Reset for new spin

                            if (history.length) {
                                computeFullTelemetry(history, info);
                            }

                            window.top.postMessage({
                                type: 'ICE_CONSOLE_ROUND',
                                sector: info.sector,
                                dir: info.direction === 'Clockwise' ? 'CW' : 'CCW',
                                activeMultCount: 0,
                                status: '[BETS OPEN]',
                                statusColor: '#00ff66',
                                resetEarly: true
                            }, '*');
                        }
                        else if (type === 'icefishing.betsClosed') {
                            window.top.postMessage({
                                type: 'ICE_CONSOLE_ROUND',
                                status: '[BETS LOCKED]',
                                statusColor: '#ff4444'
                            }, '*');
                        }
                        else if (type === 'icefishing.wheelSpinning') {
                            const multipliers = args.leafWheelMultipliers || {};
                            activeWheelMultipliers = multipliers;
                            const count = Object.keys(multipliers).length;

                            window.top.postMessage({
                                type: 'ICE_CONSOLE_ROUND',
                                activeMultCount: count
                            }, '*');
                        }
                        else if (type === 'icefishing.wheelStopping') {
                            const landedSector = args.sector;
                            let wonMult = 1;

                            // Check if landed sector had an active multiplier
                            if (activeWheelMultipliers[landedSector]) {
                                wonMult = activeWheelMultipliers[landedSector].multiplier?.value || 1;
                            }

                            window.top.postMessage({
                                type: 'ICE_CONSOLE_ROUND',
                                early: `>>> SECTOR ${landedSector}! <<<`,
                                wonMultiplier: wonMult,
                                status: '[LOCKED]',
                                statusColor: '#33ccff'
                            }, '*');
                        }
                    } catch (e) {}
                });
            }
            return ws;
        }
    });

    window.addEventListener('DOMContentLoaded', initHUD);
    setTimeout(initHUD, 1500);
})();
